        this._balance += amount;
        return this._balance;
    }
}
let acc = new BankAccount('Alice', 100);
acc.deposit(50);
console.log(`Account: ${acc.owner}, Balance: $${acc._balance}`);

codeExamples.cpp:
#include <iostream>
#include <string>
class BankAccount {
private:
    std::string owner;
    double balance;
public:
    BankAccount(std::string o, double b) : owner(o), balance(b) {}
    void deposit(double amt) { balance += amt; }
    double getBalance() const { return balance; }
};
int main() {
    BankAccount acc("Alice", 100);
    acc.deposit(50);
    std::cout << "Balance: $" << acc.getBalance() << std::endl;
    return 0;
}

